			'/T': '(' + stringToRaw(annotation.authorName) + ')',
			'/Contents':  '(' + stringToRaw(annotation.comment) + ')',
			'/NM': '(' + 'Zotero-' + annotation.id + ')',
			'/Zotero:Key': '(' + annotation.id + ')',
			'/Zotero:AuthorName': '(' + stringToRaw(annotation.authorName) + ')',
