  static #CoordsArray =
    (typeof PDFJSDev !== "undefined" && PDFJSDev.test("MOZCENTRAL")) ||
    util/* FeatureTest */.TV.isFloat16ArraySupported
      ? Float16Array
      : Float32Array;

